// Brian Kernighan：n & (n - 1) 會清掉最低位的 1
// 時間複雜度: O(1 的個數)，空間複雜度: O(1)
function hammingWeight(n) {
    let count = 0;
    while (n !== 0) {
        n &= n - 1;
        count++;
    }
    return count;
}

