# 方法一：逐位檢查
class Solution:
    def hammingWeight(self, n: int) -> int:
        count = 0
        for i in range(32):
            if (n >> i) & 1:
                count += 1
        return count


# 方法二：Brian Kernighan（推薦，迴圈次數 = 1 的個數）
class Solution:
    def hammingWeight(self, n: int) -> int:
        count = 0
        while n:
            n &= n - 1      # 消掉最右邊的 1
            count += 1
        return count


# 方法三：Python 內建
class Solution:
    def hammingWeight(self, n: int) -> int:
        return bin(n).count('1')     # 或 n.bit_count() (Python 3.10+)

