// 方法一：逐位檢查
class Solution {
public:
    int hammingWeight(uint32_t n) {
        int count = 0;
        for (int i = 0; i < 32; i++) {
            if ((n >> i) & 1) count++;
        }
        return count;
    }
};

// 方法二：Brian Kernighan（推薦）
class Solution {
public:
    int hammingWeight(uint32_t n) {
        int count = 0;
        while (n) {
            n &= (n - 1);   // 消掉最右邊的 1
            count++;
        }
        return count;
    }
};

// 方法三：查表法（韌體常用，空間換時間）
class Solution {
    // 0~255 每個數字的 1 的個數
    static uint8_t table[256];
public:
    int hammingWeight(uint32_t n) {
        return table[n & 0xFF] + table[(n >> 8) & 0xFF]
             + table[(n >> 16) & 0xFF] + table[(n >> 24) & 0xFF];
    }
};

// 方法四：編譯器內建指令（實務上最快）
int hammingWeight(uint32_t n) {
    return __builtin_popcount(n);   // GCC/Clang，會編成 POPCNT 指令
}

